CREATE TABLE IF NOT EXISTS patients (patient_id TEXT PRIMARY KEY, name TEXT NOT NULL, age INTEGER, start_date TEXT NOT NULL, end_date TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS reports (report_id TEXT PRIMARY KEY, patient_id TEXT NOT NULL REFERENCES patients(patient_id), submitted_at TEXT, report_date TEXT NOT NULL, raw_text TEXT NOT NULL, questionnaire_json TEXT NOT NULL, parser_version TEXT NOT NULL, review_needed INTEGER NOT NULL DEFAULT 0, issues_json TEXT NOT NULL DEFAULT '[]', verification_json TEXT NOT NULL DEFAULT '{"status":"not_run"}', symptom_review_json TEXT NOT NULL DEFAULT '{"status":"not_run"}');
CREATE TABLE IF NOT EXISTS symptom_observations (observation_id TEXT PRIMARY KEY, report_id TEXT NOT NULL REFERENCES reports(report_id), source TEXT NOT NULL CHECK(source IN ('text','questionnaire')), symptom TEXT NOT NULL, original_phrase TEXT, presence TEXT NOT NULL CHECK(presence IN ('present','absent','uncertain')), severity_value REAL, severity_scale TEXT, severity_text TEXT, episode_count INTEGER, observed_date TEXT, timing_text TEXT, medication_mentioned TEXT, evidence TEXT NOT NULL, issues_json TEXT NOT NULL, is_full_day INTEGER NOT NULL DEFAULT 0, count_eligible INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS medication_events (event_id TEXT PRIMARY KEY, patient_id TEXT NOT NULL REFERENCES patients(patient_id), report_id TEXT REFERENCES reports(report_id), medication TEXT NOT NULL, dose TEXT, effective_date TEXT NOT NULL, event_type TEXT NOT NULL, source TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS observations_date ON symptom_observations(observed_date, symptom);
CREATE INDEX IF NOT EXISTS reports_patient ON reports(patient_id, report_date);
